-- AlterEnum
-- This migration adds more than one value to an enum.
-- With PostgreSQL versions 11 and earlier, this is not possible
-- in a single migration. This can be worked around by creating
-- multiple migrations, each migration adding only one value to
-- the enum.


ALTER TYPE "HighSchoolSource" ADD VALUE 'NCES_CCD';
ALTER TYPE "HighSchoolSource" ADD VALUE 'NCES_PSS';
ALTER TYPE "HighSchoolSource" ADD VALUE 'OPENDATASOFT_PUBLIC';
ALTER TYPE "HighSchoolSource" ADD VALUE 'OPENDATASOFT_PRIVATE';
ALTER TYPE "HighSchoolSource" ADD VALUE 'URBAN_INSTITUTE';

-- AlterTable
ALTER TABLE "HighSchool" ADD COLUMN     "isAuthoritative" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "lastSyncedAt" TIMESTAMP(3);

-- CreateIndex
CREATE INDEX "HighSchool_source_idx" ON "HighSchool"("source");

-- CreateIndex
CREATE INDEX "HighSchool_isAuthoritative_idx" ON "HighSchool"("isAuthoritative");

-- CreateIndex
CREATE INDEX "HighSchool_lastSyncedAt_idx" ON "HighSchool"("lastSyncedAt");
